@EventBusSubscriber(modid=TC4Modern.MODID,value=net.neoforged.api.distmarker.Dist.CLIENT)
final class ElementalEarthAudit {
 static int ticks;static volatile int stage;static final BlockPos POS=InfusionAudit.POS,SHOW=POS.offset(-6,-2,8);static ItemStack shovel;
 static void check(boolean b,String s){if(!b)throw new IllegalStateException("TC4_EARTH FAIL "+s);System.out.println("TC4_EARTH PASS "+s);}
 static InteractionResult use(ServerPlayer p,BlockPos pos,Direction side){var c=new UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(pos),side,pos,false));return p.getMainHandItem().getItem().useOn(c);}
 static void patch(ServerLevel l,BlockPos center,Block block){for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++){l.setBlock(center.offset(x,0,z),block.defaultBlockState(),3);l.setBlock(center.offset(x,1,z),Blocks.AIR.defaultBlockState(),3);}}
 static void treeSpace(ServerLevel l,BlockPos root){for(int x=-9;x<=9;x++)for(int z=-9;z<=9;z++)for(int y=-1;y<=32;y++)l.setBlock(root.offset(x,y,z),y==-1?Blocks.GRASS_BLOCK.defaultBlockState():Blocks.AIR.defaultBlockState(),2);}
 static void prepare(ServerPlayer p){p.getInventory().selected=0;InfusionAudit.prepare(p);InfusionAudit.matrix.logic.crafting=false;RunicAudit.clear(p);var l=p.serverLevel();l.setDayTime(6000);l.setWeatherParameters(10000,0,false,false);shovel=new ItemStack(ElementalTools.item("shovel"));var hoe=new ItemStack(ElementalTools.item("hoe"));check(shovel.getMaxDamage()==1500&&shovel.getEnchantmentValue()==18&&hoe.getMaxDamage()==1500&&hoe.getEnchantmentValue()==5,"shovel1500/18 hoe1500/5 original rarity+material");
  p.setItemInHand(InteractionHand.MAIN_HAND,shovel);p.setYRot(0);var at=POS.offset(8,-1,8);var state=Blocks.OAK_STAIRS.defaultBlockState().setValue(StairBlock.FACING,Direction.EAST).setValue(StairBlock.HALF,Half.TOP);l.setBlock(at,state,3);for(int orientation=0;orientation<3;orientation++){for(int x=-2;x<=2;x++)for(int y=-2;y<=2;y++)for(int z=-3;z<=0;z++)if(!at.offset(x,y,z).equals(at))l.setBlock(at.offset(x,y,z),Blocks.AIR.defaultBlockState(),3);p.getInventory().setItem(2,new ItemStack(Items.OAK_STAIRS,9));shovel.setDamageValue(0);check(ElementalShovel.orientation(shovel)==orientation,"G orientation state "+orientation);check(use(p,at,Direction.NORTH)==InteractionResult.PASS,"placement keeps originalPASS "+orientation);for(int a=-1;a<=1;a++)for(int b=-1;b<=1;b++){var target=at.offset(ElementalShovel.offset(a,b,2,orientation,p)).north();check(l.getBlockState(target).equals(state),"actual placement exact copiedstairsstate "+orientation+"/"+a+"/"+b);}check(p.getInventory().getItem(2).getCount()==(orientation==0?0:1)&&shovel.getDamageValue()==(orientation==0?9:8),"actual placement original9-or8 items+durability "+orientation);ElementalShovel.toggle(shovel);}check(ElementalShovel.orientation(shovel)==0,"orientation3 wraps to0");
  var grass=POS.offset(-8,-1,8);l.setBlock(grass,Blocks.GRASS_BLOCK.defaultBlockState(),3);p.getInventory().setItem(2,new ItemStack(Items.DIRT,9));shovel.setDamageValue(0);use(p,grass,Direction.UP);check(p.getInventory().getItem(2).isEmpty()&&shovel.getDamageValue()==9&&l.getBlockState(grass.above()).is(Blocks.DIRT),"grass copies dirtfallback +9durability");
  var chest=POS.offset(9,-1,-7);l.setBlock(chest,Blocks.CHEST.defaultBlockState(),3);p.getInventory().setItem(2,new ItemStack(Items.CHEST,9));shovel.setDamageValue(0);use(p,chest,Direction.UP);check(l.isEmptyBlock(chest.above())&&p.getInventory().getItem(2).getCount()==9&&shovel.getDamageValue()==0,"source tileentity cannot be copied");
  var dig=POS.offset(-8,-1,-8);patch(l,dig,Blocks.DIRT);p.getInventory().setItem(2,ItemStack.EMPTY);p.connection.teleport(dig.getX()+.5,dig.getY()+3,dig.getZ()+.5,0,90);p.setShiftKeyDown(false);shovel.setDamageValue(0);p.gameMode.destroyBlock(dig);check(shovel.getDamageValue()==8,"nonsneak dig centerfree original8extra durability");for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)check(l.isEmptyBlock(dig.offset(x,0,z)),"actual gameMode3x3 harvest "+x+"/"+z);var followers=l.getEntitiesOfClass(ElementalTools.FollowingItem.class,new AABB(dig).inflate(3));check(followers.size()==8&&followers.stream().allMatch(i->i.getEntityData().get(ElementalTools.FollowingItem.PARTICLE)==3),"eight actual drops homing green type3");var saved=followers.get(0).saveWithoutId(new net.minecraft.nbt.CompoundTag());var copy=new ElementalTools.FollowingItem(ElementalTools.FOLLOWING.get(),l);copy.load(saved);check(copy.getEntityData().get(ElementalTools.FollowingItem.PARTICLE)==3,"followingitem originaltype NBT");patch(l,dig,Blocks.DIRT);p.setShiftKeyDown(true);shovel.setDamageValue(0);p.gameMode.destroyBlock(dig);check(shovel.getDamageValue()==1&&l.getBlockState(dig.east()).is(Blocks.DIRT),"sneak ordinary singleblock1durability");p.setShiftKeyDown(false);
  p.setItemInHand(InteractionHand.MAIN_HAND,hoe);var field=POS.offset(8,-1,-8);patch(l,field,Blocks.DIRT);use(p,field,Direction.UP);check(hoe.getDamageValue()==9,"hoe3x3 uses9durability");for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)check(l.getBlockState(field.offset(x,0,z)).is(Blocks.FARMLAND),"actual3x3 farmland "+x+"/"+z);patch(l,field,Blocks.DIRT);p.setShiftKeyDown(true);hoe.setDamageValue(0);use(p,field,Direction.UP);check(hoe.getDamageValue()==1&&l.getBlockState(field.east()).is(Blocks.DIRT),"sneak tills exactlyone");p.setShiftKeyDown(false);patch(l,field,Blocks.FARMLAND);var wheat=field.above();l.setBlock(wheat,Blocks.WHEAT.defaultBlockState(),3);hoe.setDamageValue(0);use(p,wheat,Direction.UP);check(l.getBlockState(wheat).getValue(CropBlock.AGE)>0&&hoe.getDamageValue()==1,"actual virtual bonemeal growscrop costs1");check(hoe.getDestroySpeed(Blocks.OAK_LEAVES.defaultBlockState())==1,"original hoe has no modern leafmining bonus");
  var failed=POS.offset(6,-1,-8);l.setBlock(failed.below(),Blocks.STONE.defaultBlockState(),3);l.setBlock(failed,TC4Modern.GREATWOOD_SAPLING.get().defaultBlockState(),3);hoe.setDamageValue(1481);check(use(p,failed,Direction.UP)==InteractionResult.PASS&&hoe.getDamageValue()==1481,"greatwood guard needs20durability");hoe.setDamageValue(1480);use(p,failed,Direction.UP);check(hoe.getDamageValue()==1485&&l.getBlockState(failed).is(TC4Modern.GREATWOOD_SAPLING.get()),"original failedgreatwood growth still costs5 after20guard");l.setBlock(failed,SilverwoodContent.SAPLING.get().defaultBlockState(),3);hoe.setDamageValue(1351);check(use(p,failed,Direction.UP)==InteractionResult.PASS&&hoe.getDamageValue()==1351,"silverwood guard needs150durability");hoe.setDamageValue(1350);use(p,failed,Direction.UP);check(hoe.getDamageValue()==1375&&l.getBlockState(failed).is(SilverwoodContent.SAPLING.get()),"original failedsilverwood growth still costs25 after150guard");
  for(boolean silver:new boolean[]{false,true}){var root=POS.offset(silver?30:-30,-2,25);treeSpace(l,root);l.setBlock(root,silver?SilverwoodContent.SAPLING.get().defaultBlockState():TC4Modern.GREATWOOD_SAPLING.get().defaultBlockState(),3);hoe.setDamageValue(0);use(p,root,Direction.UP);check(hoe.getDamageValue()==(silver?25:5)&&l.getBlockState(root).is(silver?SilverwoodContent.LOG.get():TC4Modern.GREATWOOD_LOG.get()),"actual successful magicaltree growth "+silver);}
  ElementalToolsAudit.start(p,"ElementalShovel");for(int x=-2;x<=2;x++)for(int z=-3;z<=1;z++){l.setBlock(SHOW.offset(x,0,z),Blocks.STONE.defaultBlockState(),3);l.setBlock(SHOW.offset(x,1,z),Blocks.AIR.defaultBlockState(),3);}l.setBlock(SHOW.above(),Blocks.STONE.defaultBlockState(),3);p.setItemInHand(InteractionHand.MAIN_HAND,shovel);shovel.setDamageValue(0);p.getAbilities().mayfly=true;p.getAbilities().flying=true;p.onUpdateAbilities();p.connection.teleport(SHOW.getX()+.5,SHOW.getY()+1,SHOW.getZ()-3,0,20);stage=1;
 }
 @SubscribeEvent static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post e){if(!Boolean.getBoolean("tc4modern.earthAuditOnly"))return;var mc=net.minecraft.client.Minecraft.getInstance();if(mc.player==null||mc.level==null)return;ticks++;var server=mc.getSingleplayerServer();var id=mc.player.getUUID();if(ticks==80)server.execute(()->prepare(server.getPlayerList().getPlayer(id)));if(ticks==180){check(stage==1,"server earthtool mechanics passed");mc.options.keyShift.setDown(true);net.minecraft.client.KeyMapping.click(com.mojang.blaze3d.platform.InputConstants.Type.KEYSYM.getOrCreate(org.lwjgl.glfw.GLFW.GLFW_KEY_G));}if(ticks==200)server.execute(()->{check(ElementalShovel.orientation(shovel)==1,"actual G packet changes shovelorientation");stage=2;});if(ticks==210){check(stage==2&&WardingClient.architectRendered>0,"G synchronizedserver and actual shovel architectoverlay rendered");LiquidDeathAudit.shot(mc,"elemental-shovel-architect.png");mc.options.keyShift.setDown(false);}if(ticks==230)server.execute(()->{var root=POS.offset(-30,-2,25);server.getPlayerList().getPlayer(id).connection.teleport(root.getX()+6,root.getY()+4,root.getZ()-9,35,-20);});if(ticks==250)LiquidDeathAudit.shot(mc,"elemental-hoe-greatwood.png");if(ticks==270)server.execute(()->{var root=POS.offset(30,-2,25);server.getPlayerList().getPlayer(id).connection.teleport(root.getX()+6,root.getY()+4,root.getZ()-9,35,-20);});if(ticks==290)LiquidDeathAudit.shot(mc,"elemental-hoe-silverwood.png");if(ticks==310)server.execute(()->server.getPlayerList().getPlayer(id).connection.teleport(POS.getX()+7,POS.getY()+2,POS.getZ()-8,40,25));if(ticks==330&&Boolean.getBoolean("tc4modern.earthQuickAuditOnly")){mc.stop();return;}if(ticks==850)server.execute(()->{var p=server.getPlayerList().getPlayer(id);ElementalToolsAudit.finish(p,"ElementalShovel");ElementalToolsAudit.start(p,"ElementalHoe");stage=3;});if(ticks==1600)server.execute(()->{ElementalToolsAudit.finish(server.getPlayerList().getPlayer(id),"ElementalHoe");stage=4;});if(ticks>=1620&&(ticks-1620)%20==0){check(stage==4,"both natural earthtoolinfusions complete");int i=(ticks-1620)/20;if(i>=3){mc.stop();return;}var inv=mc.player.getInventory();var book=new ThaumonomiconScreen(new ThaumonomiconMenu(0,inv),inv,net.minecraft.network.chat.Component.empty());book.auditOpen(thaumcraft.api.research.ResearchCategories.getResearch(i<2?"ELEMENTALSHOVEL":"ELEMENTALHOE"),i==1?2:0);mc.setScreen(book);}if(ticks>=1625&&(ticks-1625)%20==0)LiquidDeathAudit.shot(mc,"elemental-earth-book-"+(ticks-1625)/20+".png");}
}
